"""tools/generate_shared_code.py: the shared tables are valid, the committed code is what they give, bad tables fail."""

from __future__ import annotations

import io
import json
import shutil
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))

import generate_shared_code as generator  # noqa: E402

OUTPUTS = (generator.KOTLIN_OUTPUT, generator.SWIFT_OUTPUT, generator.TYPESCRIPT_OUTPUT)


class Workspace:
    """A copy of the tables and the generated files, to break one at a time."""

    def __init__(self) -> None:
        self._directory = tempfile.TemporaryDirectory(prefix="shared-data-")
        self.root = Path(self._directory.name)
        shutil.copytree(ROOT / generator.DATA_DIR, self.root / generator.DATA_DIR)
        for path in OUTPUTS:
            (self.root / path).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(ROOT / path, self.root / path)

    def __enter__(self) -> "Workspace":
        return self

    def __exit__(self, *_: object) -> None:
        self._directory.cleanup()

    def table(self, name: str) -> Path:
        return self.root / generator.DATA_DIR / name

    def edit(self, name: str, change) -> None:
        path = self.table(name)
        document = json.loads(path.read_text(encoding="utf-8"))
        change(document)
        path.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    def run(self, *, check: bool) -> tuple[int, str, str]:
        out, err = io.StringIO(), io.StringIO()
        status = generator.run(self.root, check=check, out=out, err=err)
        return status, out.getvalue(), err.getvalue()

    def outputs(self) -> dict[Path, bytes]:
        return {path: (self.root / path).read_bytes() for path in OUTPUTS if (self.root / path).exists()}


class CommittedCodeTest(unittest.TestCase):
    def test_the_generated_files_are_what_the_tables_give(self) -> None:
        out, err = io.StringIO(), io.StringIO()
        self.assertEqual(0, generator.run(ROOT, check=True, out=out, err=err), err.getvalue())

    def test_generation_is_deterministic(self) -> None:
        first, errors = generator.load_tables(ROOT)
        self.assertEqual([], errors)
        second, _ = generator.load_tables(ROOT)
        self.assertEqual(generator.render_outputs(first), generator.render_outputs(second))

    def test_headers_name_the_generator_and_the_sources_and_forbid_editing(self) -> None:
        loaded, _ = generator.load_tables(ROOT)
        for path, text in generator.render_outputs(loaded).items():
            with self.subTest(path=path.as_posix()):
                head = text.split("\n\n", 1)[0]
                self.assertTrue(head.startswith("// Generated by tools/generate_shared_code.py. Do not edit"), head)
                tables = loaded if path != generator.TYPESCRIPT_OUTPUT else [t for t in loaded if t.table.alexa]
                for table in tables:
                    self.assertIn(f"//   contracts/shared-data/v1/{table.table.file}", head)

    def test_alexa_gets_only_the_tables_it_reads(self) -> None:
        typescript = (ROOT / generator.TYPESCRIPT_OUTPUT).read_text(encoding="utf-8")
        alexa = {table.name for table in generator.TABLES if table.alexa}
        # The pack roles and the number prefixes since the skill reads the programmed timetable.
        self.assertEqual({"ItalianHolidays", "PackRoles", "Punctuality", "TrainNumberPrefixes"}, alexa)
        for table in generator.TABLES:
            with self.subTest(table=table.name):
                self.assertEqual(table.alexa, f"export const {table.name}: {{" in typescript)

    def test_the_apps_read_constants_as_code_not_the_json(self) -> None:
        kotlin = (ROOT / generator.KOTLIN_OUTPUT).read_text(encoding="utf-8")
        swift = (ROOT / generator.SWIFT_OUTPUT).read_text(encoding="utf-8")
        self.assertIn("internal object SharedData {", kotlin)
        self.assertIn("        const val MINIMUM_SAMPLES: Int = 5", kotlin)
        self.assertIn('        val HIGH_SPEED_CATEGORIES: Set<String> = setOf("FR", "FA", "FB", "EC", "ES", "ESC", "EN", "ITALO")', kotlin)
        self.assertIn("public enum SharedData {", swift)
        self.assertIn("        public static let minimumSamples: Int = 5", swift)
        self.assertIn("        public struct Route: Hashable, Sendable {", swift)
        self.assertNotIn("import Foundation", swift)

    def test_app_code_names_the_tables_only_in_comments(self) -> None:
        # The apps read the generated constants; a registered table named outside a comment would be a runtime read.
        # A table not registered yet (from another branch) is not checked until it is.
        tables = tuple(f"shared-data/v1/{table.file}" for table in generator.TABLES)
        sources = [
            *(ROOT / "app/src/main/java").rglob("*.kt"),
            *(ROOT / "ios/BinarioKit/Sources").rglob("*.swift"),
            *(ROOT / "ios/BinarioApp").rglob("*.swift"),
            *(path for path in (ROOT / "alexa-companion/server").rglob("*.ts") if not path.name.endswith(".test.ts")),
            *(ROOT / "alexa-companion/shared").rglob("*.ts"),
        ]
        named = 0
        for path in sources:
            for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
                if any(table in line for table in tables):
                    named += 1
                    with self.subTest(path=path.relative_to(ROOT).as_posix(), line=number):
                        self.assertTrue(line.lstrip().startswith(("//", "*", "/*")), line)
        self.assertGreater(named, 10)


class EmitterTest(unittest.TestCase):
    def test_strings_are_escaped_for_each_language(self) -> None:
        text = generator.Text()
        self.assertEqual('"a\\"b\\\\c\\$d"', generator.Kotlin().scalar(text, 'a"b\\c$d'))
        self.assertEqual('"a\\"b\\\\c$d"', generator.Swift().scalar(text, 'a"b\\c$d'))
        self.assertEqual('"a\\"b\\\\c$d"', generator.TypeScript().scalar(text, 'a"b\\c$d'))

    def test_constant_names(self) -> None:
        self.assertEqual("MINIMUM_PLATFORM_SHARE_PERCENT", generator.constant_name("minimumPlatformSharePercent"))
        self.assertEqual("SLUGS_BY_NAME", generator.constant_name("slugsByName"))

    def test_empty_and_nullable_values(self) -> None:
        names = generator.ListOf(generator.Text(), min_items=0)
        self.assertEqual("emptyList()", generator.Kotlin().inline(names, []))
        self.assertEqual("[]", generator.Swift().inline(names, []))
        year = generator.Nullable(generator.Integer())
        self.assertEqual(("null", "nil", "null"), tuple(language.inline(year, None) for language in (
            generator.Kotlin(), generator.Swift(), generator.TypeScript())))
        self.assertEqual("readonly (number | null)[]", generator.TypeScript().type_name(generator.ListOf(year)))

    def test_seconds_are_time_intervals_in_swift_and_numbers_are_doubles(self) -> None:
        seconds, real = generator.Seconds(), generator.Real()
        self.assertEqual(("Int", "Double", "number"), tuple(language.type_name(seconds) for language in (
            generator.Kotlin(), generator.Swift(), generator.TypeScript())))
        self.assertEqual("900", generator.Swift().inline(seconds, 900))
        self.assertEqual(("Double", "Double", "number"), tuple(language.type_name(real) for language in (
            generator.Kotlin(), generator.Swift(), generator.TypeScript())))
        self.assertEqual(["10.9", "45.0"], [generator.Kotlin().inline(real, value) for value in (10.9, 45.0)])

    def test_the_notes_of_a_table_are_comments_of_the_code(self) -> None:
        kotlin = (ROOT / generator.KOTLIN_OUTPUT).read_text(encoding="utf-8")
        # italo-gtfs-station-codes.json writes its notes as "comment".
        self.assertIn('            // Padova ("Padua" in the feed)\n            StationCode(code = "PD_", catalogueId = "S02581"),', kotlin)
        self.assertIn('            // Roma Termini ↔ Fiumicino Aeroporto (Trenitalia regional express).\n', kotlin)


class ValidationTest(unittest.TestCase):
    def assert_refused(self, workspace: Workspace, fragment: str) -> None:
        before = workspace.outputs()
        for check in (True, False):
            status, _, err = workspace.run(check=check)
            self.assertEqual(1, status, err)
            self.assertIn(fragment, err)
            self.assertIn("Nessun file generato", err)
        self.assertEqual(before, workspace.outputs(), "a refused table must not write anything")

    def test_a_repeated_key_is_refused(self) -> None:
        with Workspace() as workspace:
            path = workspace.table("rfi-place-ids-v1.json")
            text = path.read_text(encoding="utf-8")
            path.write_text(text.replace('"Roma Termini": 2416,', '"Roma Termini": 2416,\n    "Roma Termini": 2417,'), encoding="utf-8")
            self.assert_refused(workspace, "chiave ripetuta 'Roma Termini'")

    def test_unknown_missing_and_mistyped_keys_are_refused(self) -> None:
        cases = (
            ("punctuality-v1.json", lambda d: d.update(extra=1), "chiave non prevista 'extra'"),
            ("punctuality-v1.json", lambda d: d.pop("minimumSamples"), "manca la chiave 'minimumSamples'"),
            ("punctuality-v1.json", lambda d: d.update(minimumSamples="5"), "atteso un intero"),
            ("punctuality-v1.json", lambda d: d.update(minimumSamples=True), "atteso un intero"),
            ("punctuality-v1.json", lambda d: d.update(minimumSamples=0), "minore di 1"),
            ("punctuality-v1.json", lambda d: d.update(schema="other"), "schema deve essere"),
            ("airport-routes-v1.json", lambda d: d["routes"][0].update(cityLine=True), "chiave non prevista 'cityLine'"),
            ("airport-routes-v1.json", lambda d: d["packs"][0].update(cityLine="no"), "atteso un booleano"),
            ("italo-stations-v1.json", lambda d: d["stations"][0].update(code="MILANO"), "non corrisponde"),
            ("italo-stations-v1.json", lambda d: d["stations"][0].update(name="Milano\tCentrale"), "caratteri di controllo"),
            ("italo-stations-v1.json", lambda d: d["stations"][0].update(name=" Milano"), "spazi ai bordi"),
            ("train-number-prefixes-v1.json", lambda d: d.update(categories=[]), "almeno 1 elementi"),
            ("train-number-prefixes-v1.json", lambda d: d["categories"].append("R|S"), "non corrisponde"),
            ("italo-gtfs-station-codes.json", lambda d: d.update(name="other"), "name deve essere 'italo-gtfs-station-codes'"),
            ("italo-gtfs-station-codes.json", lambda d: d["readers"].update(android=1), "attesa una stringa"),
            ("italo-gtfs-station-codes.json", lambda d: d["codes"][0].update(note="x"), "chiave non prevista 'note'"),
            ("notices-sources-v1.json", lambda d: d["trenord"]["area"].update(maximumLatitude="46"), "atteso un numero"),
            ("notices-sources-v1.json", lambda d: d["trenord"]["area"].update(maximumLatitude=True), "atteso un numero"),
            ("notices-sources-v1.json", lambda d: d["sources"][0].update(gate="sometimes"), "non corrisponde"),
            ("notices-sources-v1.json", lambda d: d["sources"][0].update(url="http://scioperi.mit.gov.it/rss"), "non corrisponde"),
            ("source-manners-v1.json", lambda d: d.update(refusalPauseSeconds=-1), "minore di 1"),
        )
        for name, change, fragment in cases:
            with self.subTest(name=name, fragment=fragment), Workspace() as workspace:
                workspace.edit(name, change)
                self.assert_refused(workspace, fragment)

    def test_duplicate_entries_are_refused(self) -> None:
        cases = (
            ("italo-stations-v1.json", lambda d: d["stations"].append({"code": "MC_", "name": "Milano"}), "code ripetuto"),
            ("punctuality-v1.json", lambda d: d["highSpeedCategories"].append("FR"), "valore ripetuto"),
            ("source-scores-v1.json", lambda d: d["preferences"].append(dict(d["preferences"][0], score=1)), "source/category ripetuto"),
            ("italian-holidays-v1.json", lambda d: d["holidays"].append({"month": 1, "day": 1, "fromYear": 2030}), "month/day ripetuto"),
        )
        for name, change, fragment in cases:
            with self.subTest(name=name), Workspace() as workspace:
                workspace.edit(name, change)
                self.assert_refused(workspace, fragment)

    def test_the_cross_checks_of_each_table(self) -> None:
        cases = (
            ("airport-routes-v1.json", lambda d: d["routes"][0].update(packs=["unknown-gtfs"]), "non dichiarato in packs"),
            ("airport-routes-v1.json", lambda d: d["packs"].append({"id": "spare-gtfs", "cityLine": False}), "non usato"),
            ("airport-routes-v1.json", lambda d: d["routes"][0].update(airport=d["routes"][0]["city"]), "coincidono"),
            ("source-scores-v1.json", lambda d: d["preferences"][0].update(category="LIVE"), "non in categories"),
            ("source-scores-v1.json", lambda d: d["operatorAffinity"][1]["sources"].append("ch-otd-gtfs"), "già in operatorAffinity[0]"),
            ("source-scores-v1.json", lambda d: d["operatorAffinity"][0]["pointsByCategory"].pop("ROUTE_VARIATIONS"),
             "pointsByCategory deve elencare categories"),
            ("italian-holidays-v1.json", lambda d: d["holidays"].append({"month": 2, "day": 30}), "non è una data"),
            ("planned-journeys-v1.json", lambda d: d["reminderMinutes"].reverse(), "in ordine crescente"),
            ("italo-gtfs-station-codes.json", lambda d: d["unmapped"].append({"code": "MC_"}), "è anche in codes"),
            ("notices-sources-v1.json", lambda d: d["months"].pop(), "dodici mesi"),
            ("notices-sources-v1.json", lambda d: d["trenord"]["area"].update(minimumLatitude=50.0), "minimo non minore"),
            ("source-manners-v1.json", lambda d: d.update(userAgent="Binario (rail timetable app)"), "un solo <version>"),
            ("pack-roles-v1.json", lambda d: d["foreignPacks"].append("italo-gtfs"), "sia nazionale sia estero"),
            ("delay-compensation-v1.json", lambda d: d.update(halfFromMinutes=60), "quarterFromMinutes non minore"),
            ("delay-compensation-v1.json", lambda d: d.update(halfPercent=25), "quarterPercent non minore"),
            ("destination-weather-v1.json", lambda d: d.update(forecastDays=17), "16"),
            ("destination-weather-v1.json", lambda d: d.update(readTimeoutSeconds=20), "readTimeoutSeconds maggiore"),
            ("bike-sharing-v1.json", lambda d: d["systems"][0].update(attribution="CC0"), "non nomina il sistema"),
            ("bike-sharing-v1.json", lambda d: d["systems"][1].update(discoveryUrl="http://gbfs.nextbike.net/x.json"), "systems"),
            ("live-train-map-v1.json", lambda d: d.update(timetableSlotMinutes=7), "non divide l'ora"),
            ("evening-alerts-v1.json", lambda d: d.update(strikeReminderHour=23), "nelle ore di quiete"),
        )
        for name, change, fragment in cases:
            with self.subTest(name=name, fragment=fragment), Workspace() as workspace:
                workspace.edit(name, change)
                self.assert_refused(workspace, fragment)

    def test_nan_and_comment_breakers_are_refused(self) -> None:
        with Workspace() as workspace:
            path = workspace.table("punctuality-v1.json")
            path.write_text(path.read_text(encoding="utf-8").replace('"minimumSamples": 5', '"minimumSamples": NaN'), encoding="utf-8")
            self.assert_refused(workspace, "valore non ammesso NaN")
        with Workspace() as workspace:
            workspace.edit("airport-routes-v1.json", lambda d: d["routes"][0].update(note="ends */ here"))
            self.assert_refused(workspace, "non ammesso in un commento")

    def test_registry_names_must_be_identifiers_in_every_language(self) -> None:
        bad = generator.Table("bad-v1.json", "Bad", {"default": generator.Field(generator.Integer())})
        self.assertTrue(any("'default'" in problem for problem in generator.check_registry((bad,))))
        clash = generator.Table("clash-v1.json", "Punctuality", {"value": generator.Field(generator.Integer())})
        self.assertTrue(any("ripetuto" in problem for problem in generator.check_registry(generator.TABLES + (clash,))))
        self.assertEqual([], generator.check_registry(generator.TABLES))


class CheckModeTest(unittest.TestCase):
    def test_check_fails_on_a_stale_or_missing_file_and_writing_fixes_it(self) -> None:
        with Workspace() as workspace:
            workspace.edit("punctuality-v1.json", lambda d: d.update(minimumSamples=6))
            status, _, err = workspace.run(check=True)
            self.assertEqual(1, status)
            for path in OUTPUTS:
                self.assertIn(f"{path.as_posix()} non corrisponde", err)
            (workspace.root / generator.SWIFT_OUTPUT).unlink()
            status, out, _ = workspace.run(check=False)
            self.assertEqual(0, status)
            self.assertIn("scritto ios/BinarioKit/Sources/BinarioKit/Generated/SharedData.swift", out)
            self.assertIn("const val MINIMUM_SAMPLES: Int = 6", (workspace.root / generator.KOTLIN_OUTPUT).read_text(encoding="utf-8"))
            self.assertEqual(0, workspace.run(check=True)[0])

    def test_a_table_not_registered_yet_is_reported_and_generates_nothing(self) -> None:
        with Workspace() as workspace:
            workspace.table("future-table-v1.json").write_text('{"schema": "anything"}\n', encoding="utf-8")
            status, _, err = workspace.run(check=True)
            self.assertEqual(0, status, err)
            self.assertIn("contracts/shared-data/v1/future-table-v1.json non è registrato", err)


if __name__ == "__main__":
    unittest.main()
